/*
 * test_rsa_pem_encoder.cpp
 *
 * This file contains the unit tests for the ASN.1 DER encoding/ decoding implementation.
 */

#include "asn1/pem/pem.h"

#include <gtest/gtest.h>

// ===== RSA PUBLIC KEY =====

TEST(PEMEncoder_RSA_Test, encode_decode_rsa_public_pkcs8) {
    RSAPublicKey key = {
        "0xa399caf6d93b62a6b6a5311efe93c4d647397ca05a98fa5cddb72d6816ab16fc85f940efe9cf2233975c8925c60f4cd356767cc8445686313a0caeae32930070ca90591a1b249c2fcef9280f5a11d8f1990579d86a05b2523f52c4a876da2d635ca27fbff195e6f7015f834928f033a20b2cd0216a852958b3e58d0f9bd54233",
        65537
    };

    PEMEncoder encoder;
    std::string pem = encoder.encodeRSAPublicKeyToPKCS8(key);
   
    RSAPublicKey decoded = PEMDecoder::decodeRSAPublicKeyFromPKCS8(pem);

    EXPECT_EQ(key.n, decoded.n);
    EXPECT_EQ(key.e, decoded.e);
}

TEST(PEMEncoder_RSA_Test, encode_decode_rsa_public_pkcs1) {
    RSAPublicKey key = {
        "0xa8f7e069311610fdd2f70d2d82c89c5117e8fa72d6d3dff429f38f8a7858678a2ecd4fb7c42e294a5129f14b7d1602f4020a8db2535a2b7e0aabe3598cef4301",
        65537
    };

    PEMEncoder encoder;
    std::string pem = encoder.encodeRSAPublicKeyToPKCS1(key);

    RSAPublicKey decoded = PEMDecoder::decodeRSAPublicKeyFromPKCS1(pem);

    EXPECT_EQ(key.n, decoded.n);
    EXPECT_EQ(key.e, decoded.e);
}

TEST(PEMEncoder_RSA_Test, encode_decode_rsa_private_pkcs8) {
    static RSAKeyPair key = {
        RSAPrivateKey{
            "",
            "0x00fe0ca20225940620811d13688c6a296c4d3b22ff26fd08163c5f0f7c6f7a9527f374f6a1a69eb239f0063e0722fee2a4068147d05cdd276814236621b0f493d5fcfc0b8225ed3d5f5bb320eb2135365613b3ed94fd22bf263b5627202d08d412d1a3aa9fd33049e7a3968661556ce065ebad2a93f9ce759fd936c4f6ba60eaf7",
            "0x00e901b491774f5870ea75da6d4adeafd559a07a99f1d1d0ad74f21df304b683fe7388fc6c2f048dfb3bc0db12ac7ef01d590501885fdab2f247d02e45a4b4700bcc9bbb9fcc77ef8f45f99462b927cf9ce34ba7e8be05ada6f60aaff9cd2a67d580ab41ab79b6ef1a49cb67df8ba4dae8cd77c77128f88d28d591a9045965081b",
            "0x00d53b0733e41494fbed42d94a74289af202f4b2d0140a67223ab3d30caf88e4ee6e626aab8d6d3fcc6f50ddf9217f6bfd1e549e511dd0a5c5aeb9737cadc8ead8be0953237eefdc0650b24ddbecb87c0dcd65c4f0bb72d19ba64c0e74ec37afc0c7e2a6509572bf65442210525be0118c9a3e73315687daa43b2dc42e0e8b504b",
            "0x078f049a8b72497e303cee7f0924bc33819ad11f5956e31c1d65154fa2e180daaa48d1577916febc1dae1ded37274f06c4b282e037abd28e45821d5e28ffa97ad8825ccdcc463fc13815e69865454358e58eb8bdb61c5d0bc383893de347f2e25c30320b2c01a1340b1ccc1bd65ddcb41ca63c1411ae2e761aa785021d1c47ed",
            "0x5c64fe3173df0c11b7b4a3e3f9d16b64ee39f86d31d95260708b5a937a8b76ecce30ced2a843db57064164a2919b682da721c7f8aaf6c95a2fa91b7656a5a074dccb3c8995e573f97358066f33fa954bf1764fa94a87390df0e4638bcf696f6df73aea1e1ea40a9575e173413ec376dae1a8ef09a24f66f232bdd2f6b7de9d12"
        },
        RSAPublicKey{
            "",
            65537
        }
    };

    PEMEncoder encoder;
    std::string pem = encoder.encodeRSAPrivateKeyToPKCS8(key);

    RSAKeyPair decoded = PEMDecoder::decodeRSAPrivateKeyFromPKCS8(pem);

    EXPECT_EQ(key.getPublicKey().n, decoded.getPublicKey().n);
    EXPECT_EQ(key.getPublicKey().e, decoded.getPublicKey().e);
    EXPECT_EQ(key.getPrivateKey().d, decoded.getPrivateKey().d);
    EXPECT_EQ(key.getPrivateKey().p, decoded.getPrivateKey().p);
    EXPECT_EQ(key.getPrivateKey().q, decoded.getPrivateKey().q);
    EXPECT_EQ(key.getPrivateKey().dP, decoded.getPrivateKey().dP);
    EXPECT_EQ(key.getPrivateKey().dQ, decoded.getPrivateKey().dQ);
    EXPECT_EQ(key.getPrivateKey().qInv, decoded.getPrivateKey().qInv);
}

TEST(PEMEncoder_RSA_Test, encode_decode_rsa_private_pkcs1) {
    RSAKeyPair key = {
        RSAPrivateKey{
            "",
            "0xA47713084FCCCF66CA2D1064C83BEB8294EFE49D0C18159F8D566D981985D25A361A3AD5D6893F886610C9AD85EB956BD1407FEC73A65C3678C8575885CDD24C201135192264CE7F8C7E0EF6A5A39B66AB66E5D530F020E88D1446A585BC218C245D6C49DB57B8B57869FD77B92D71EE13C5D09A570BC66664183CA2F183A871",
            "0x98BFBCA288BBB477D4BA790F01158B11BC550710822C75D25FF0B44F870DCFB2FA3AA1B7743A997F3E2B0F69F0051CF17AE08FEEEB9255F7DB5C35395DCF3F8A7303298BC0A374FCF391C931B6F62C32666EC1734BB150A84A8F3BB6CA52DFA97B56DC3E4ACF2578FF2D2231B5207B71BA92A1671D36E47E19DD5777E835D083",
            "0x3606EBD8AA2654E7A678E14ECA3C6CE46BBAD6B6049810DA661AC34BD8EE8E2896674D769BD0606F955FE470BD72A396549A44ABCF5E1222CED0B968DA23BFF6C3FE031C6BA103F9009514A34FCC8C2B51192F5D36835BBC294444E4F126D93A6963CB4403EB304164FA248AE4E919E924D3B1F051B20B8DED49CCF9962F32F1",
            "0x82677E958C0223CA01D4C8B1248DCDD270646EC98B3885C5FA9E367186AD25DA788241B9AB02B434CB505BB2677516069A8EC892828EC5D1FA76380227B25D5EC75DB5C457CBB47E973AA8F74669D7C597698AC1F1A70963037450D876D655980D725448E1F902D6CF932A94213BFFE7520F08B84D5AA5AB7A4D5AF5454B5C1D",
            "0x3E7B51F289D69779B125FDDF09988F3C4699491FB7F3F9C584CA32D7B9D5C0C6E30A5186E51F3DD77D9E6D99BB2C6E1C83D15EF4832D576DE5B12FD991F53B842CADC16A2547A1C2CA34E70A6CC8DF9A6DD7D6B2CE3326927F3F69BFFFEC6FE5689BF6B2F16D46D653820879A9D32DAC8F46732658F2940B08E9B10C794B7C88"
        },
        RSAPublicKey{
            "",
            65537
        }
    };

    PEMEncoder encoder;
    std::string pem = encoder.encodeRSAPrivateKeyToPKCS1(key);

    RSAKeyPair decoded = PEMDecoder::decodeRSAPrivateKeyFromPKCS1(pem);

    EXPECT_EQ(key.getPublicKey().n, decoded.getPublicKey().n);
    EXPECT_EQ(key.getPublicKey().e, decoded.getPublicKey().e);
    EXPECT_EQ(key.getPrivateKey().d, decoded.getPrivateKey().d);
    EXPECT_EQ(key.getPrivateKey().p, decoded.getPrivateKey().p);
    EXPECT_EQ(key.getPrivateKey().q, decoded.getPrivateKey().q);
    EXPECT_EQ(key.getPrivateKey().dP, decoded.getPrivateKey().dP);
    EXPECT_EQ(key.getPrivateKey().dQ, decoded.getPrivateKey().dQ);
    EXPECT_EQ(key.getPrivateKey().qInv, decoded.getPrivateKey().qInv);
}
